<?php
header('Content-Type: application/json; charset=utf-8');
header('X-Content-Type-Options: nosniff');
$dir=__DIR__.'/data'; if(!is_dir($dir)) mkdir($dir,0750,true); $pdo=new PDO('sqlite:'.$dir.'/students.sqlite'); $pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION); $pdo->exec("CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,address TEXT NOT NULL,phone TEXT NOT NULL,grade TEXT NOT NULL,stage TEXT NOT NULL,guardian TEXT DEFAULT '',guardian_email TEXT DEFAULT '',birth_date TEXT DEFAULT '',notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP)"); $pdo->exec("CREATE TABLE IF NOT EXISTS grades(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,semester INTEGER NOT NULL,arabic REAL DEFAULT 0,english REAL DEFAULT 0,math REAL DEFAULT 0,science REAL DEFAULT 0,social REAL DEFAULT 0,religion REAL DEFAULT 0,UNIQUE(student_id,semester),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE)");
function out($x,$s=200){http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE);exit;} function input(){return json_decode(file_get_contents('php://input'),true)?:$_POST;} function val($d,$k,$req=true){$v=trim((string)($d[$k]??''));if($req&&$v==='')out(['error'=>"الحقل $k مطلوب"],422);return $v;}
$method=$_SERVER['REQUEST_METHOD'];$d=input();$stages=['ابتدائي','أولى متوسط','ثانية متوسط','ثالثة متوسط','رابعة متوسط','أولى ثانوي','ثانية ثانوي','ثالثة ثانوي'];try{if($method==='GET'){if(($_GET['action']??'')==='grades'){$q=$pdo->prepare('SELECT * FROM grades WHERE student_id=? ORDER BY semester');$q->execute([(int)$_GET['id']]);out(['grades'=>$q->fetchAll(PDO::FETCH_ASSOC)]);} $sql='SELECT * FROM students WHERE 1=1';$p=[];if(($q=trim($_GET['search']??''))!==''){$sql.=' AND(name LIKE :q OR phone LIKE :q OR address LIKE :q OR guardian LIKE :q)';$p[':q']="%$q%";}if(in_array($_GET['stage']??'',$stages,true)){$sql.=' AND stage=:stage';$p[':stage']=$_GET['stage'];}$q=$pdo->prepare($sql.' ORDER BY id DESC');$q->execute($p);out(['students'=>$q->fetchAll(PDO::FETCH_ASSOC)]);} if($method==='POST'){$stage=val($d,'stage');if(!in_array($stage,$stages,true))out(['error'=>'المرحلة غير صحيحة'],422);$q=$pdo->prepare('INSERT INTO students(name,address,phone,grade,stage,guardian,guardian_email,birth_date,notes) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([val($d,'name'),val($d,'address'),val($d,'phone'),val($d,'grade'),$stage,val($d,'guardian',false),val($d,'guardianEmail',false),val($d,'birthDate',false),val($d,'notes',false)]);$id=$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO grades(student_id,semester) VALUES(?,?)');for($i=1;$i<=3;$i++)$q->execute([$id,$i]);out(['message'=>'تمت إضافة الطالب بنجاح'],201);} $id=(int)($_GET['id']??$d['id']??0);if($id<1)out(['error'=>'معرّف غير صحيح'],422);if($method==='PUT'&&($_GET['action']??'')==='grades'){$s=(int)($d['semester']??0);if($s<1||$s>3)out(['error'=>'الفصل يجب أن يكون 1 أو 2 أو 3'],422);$q=$pdo->prepare('UPDATE grades SET arabic=?,english=?,math=?,science=?,social=?,religion=? WHERE student_id=? AND semester=?');$q->execute([(float)($d['arabic']??0),(float)($d['english']??0),(float)($d['math']??0),(float)($d['science']??0),(float)($d['social']??0),(float)($d['religion']??0),$id,$s]);out(['message'=>'تم حفظ الدرجات']);}if($method==='PUT'){$stage=val($d,'stage');if(!in_array($stage,$stages,true))out(['error'=>'المرحلة غير صحيحة'],422);$q=$pdo->prepare('UPDATE students SET name=?,address=?,phone=?,grade=?,stage=?,guardian=?,guardian_email=?,birth_date=?,notes=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$q->execute([val($d,'name'),val($d,'address'),val($d,'phone'),val($d,'grade'),$stage,val($d,'guardian',false),val($d,'guardianEmail',false),val($d,'birthDate',false),val($d,'notes',false),$id]);out(['message'=>'تم تحديث بيانات الطالب']);}if($method==='DELETE'){$q=$pdo->prepare('DELETE FROM students WHERE id=?');$q->execute([$id]);out(['message'=>'تم حذف الطالب ودرجاته']);}out(['error'=>'طريقة غير مدعومة'],405);}catch(Throwable $e){error_log($e->getMessage());out(['error'=>'حدث خطأ في الخادم'],500);}
